struct MatchRecord {
  enum MatchWinner : std::uint8_t { draw = 0, a = 1, b = 2 };

  std::uint64_t key = 0;       // caller-chosen identity, stable across retries
  std::uint64_t round = 0;
  std::uint64_t player_a = 0;
  std::uint64_t player_b = 0;
  std::uint64_t ticks = 0;
  std::uint64_t score_a = 0;
  std::uint64_t score_b = 0;
  std::uint32_t lines_a = 0;
  std::uint32_t lines_b = 0;
  MatchWinner winner = draw;
};

bool prepare(const MatchRecord& record) noexcept {
  if (state_ != SubmissionState::empty) return false;
  if (!is_valid(record)) return false;
  request_ = record;              // fixed-size copy into inline storage
  state_ = SubmissionState::ready;
  return true;
}

const MatchRecord* request() const noexcept {
  return request_.has_value() ? &request_.value() : nullptr;
}

template <typename Sender>
SubmitStep submit(Sender&& sender) {
  static_assert(
      std::is_nothrow_invocable_r_v<Reply, Sender, const MatchRecord&>,
      "Sender must be noexcept-invocable as Reply(const MatchRecord&)");

  if (state_ == SubmissionState::empty ||
      state_ == SubmissionState::confirmed) {
    return SubmitStep::no_work;
  }
  if (attempts_ >= max_attempts_) {
    // Budget spent: do not call. Preserve ready/unconfirmed, never map to a
    // definitive rejection.
    return SubmitStep::budget_exhausted;
  }

  ++attempts_;
  state_ = SubmissionState::unconfirmed;  // set before the callback runs
  const Reply reply = std::forward<Sender>(sender)(request_.value());

  if (reply.kind == Reply::confirmed && accepts(reply.receipt)) {
    receipt_ = reply.receipt;
    state_ = SubmissionState::confirmed;
    return SubmitStep::confirmed;
  }
  // Invalid or unconfirmed reply: stay unconfirmed. "Unconfirmed" only
  // means we did not learn that the record was stored, so the caller may
  // retry this same instance with the same immutable body and key.
  return SubmitStep::unconfirmed;
}

bool accepts(const Receipt& receipt) const noexcept {
  const MatchRecord& r = request_.value();
  return receipt.key == r.key && receipt.row > 0 &&
         receipt.player_a == r.player_a && receipt.player_b == r.player_b;
}

const auto& terminal=authority.game()->state();
const bool a_lost=terminal.left().finished(),b_lost=terminal.right().finished();
require(a_lost || b_lost);
require(terminal.left().total_lines()<=std::numeric_limits<std::uint32_t>::max() &&
        terminal.right().total_lines()<=std::numeric_limits<std::uint32_t>::max());
MatchRecord record;
record.key=17;record.round=1;record.player_a=101;record.player_b=202;
record.ticks=ticks;record.score_a=terminal.left().score();record.score_b=terminal.right().score();
record.lines_a=static_cast<std::uint32_t>(terminal.left().total_lines());
record.lines_b=static_cast<std::uint32_t>(terminal.right().total_lines());
record.winner=a_lost && b_lost ? MatchRecord::draw : a_lost ? MatchRecord::b : MatchRecord::a;

struct ReceiptService {
    std::optional<MatchRecord> stored;
    unsigned writes=0;
    Reply operator()(const MatchRecord& record) noexcept {
        if(!stored) {
            stored=record;++writes;
            return {}; // Applied, but the caller learns nothing from this reply.
        }
        if(*stored!=record)return {}; // Never confirm a changed operation.
        return {Reply::confirmed,{record.key,1,record.player_a,record.player_b}};
    }
};

MatchSubmission submission(3);require(submission.prepare(record));
ReceiptService service;
require(submission.submit(service)==MatchSubmission::SubmitStep::unconfirmed);
require(service.writes==1 && !submission.receipt());
require(submission.submit(service)==MatchSubmission::SubmitStep::confirmed);
require(service.writes==1 && submission.receipt()->row==1 && submission.attempts()==2);
auto conflicting=record;++conflicting.score_a;
require(service(conflicting).kind==Reply::unconfirmed && service.writes==1);
require(submission.submit(service)==MatchSubmission::SubmitStep::no_work);
